27: export async function safeExtractDocxFromBuffer(buffer: Buffer): Promise<string> {
28:   if (!buffer || buffer.length === 0) {
29:     throw new Error('Invalid DOCX data: Buffer is empty');
30:   }
31: 
32:   if (buffer.length > MAX_DOCX_BYTES) {
33:     throw new DocxSecurityError(
34:       `Security Error: File size (${buffer.length} bytes) exceeds maximum allowed size of ${MAX_DOCX_BYTES} bytes (5MB)`
35:     );
36:   }
37: 
38:   // Mammoth handles XML parsing in-memory (XXE-safe, no disk extraction)
39:   const result = await mammoth.extractRawText({ buffer });
