56:   const chunks: Buffer[] = [];
57:   let totalBytes = 0;
58: 
59:   try {
60:     for await (const chunk of stream) {
61:       const bufChunk = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
62:       totalBytes += bufChunk.length;
